<script setup>
import { computed, nextTick, ref } from 'vue';
import { FormKitSchema } from '@formkit/vue';
import { FontAwesomeIcon } from '@fortawesome/vue-fontawesome';
import IconButton from './IconButton.vue';
import * as icons from './icons.js';
import { settingsCards, settingsSchemas, backendSchema, defaultSettings, copy, aboutLinks } from './settings-data.js';
const props=defineProps({capabilities:{type:Object,default:()=>({share:true,archive:true,node:true})},environment:{type:Object,default:()=>({backend:'Node',version:'未连接',hasNewVersion:false,name:'示例后端'})}});
const emit=defineEmits(['open-logs','change','navigate']);
const storageKey='sub-store-design-settings-v2';
const clone=value=>JSON.parse(JSON.stringify(value));
function read(){try{const cached=JSON.parse(localStorage.getItem(storageKey)||'null');return cached?.version===2?{...clone(defaultSettings),...cached.values}:clone(defaultSettings)}catch{return clone(defaultSettings)}}
const settings=ref(read());const panel=ref('');const dialog=ref();const draft=ref({});const notice=ref('');const backendEdit=ref(null);const backendDraft=ref({name:'',url:'',shareBaseUrl:''});const backendError=ref('');const duplicateBackend=ref(null);const confirmation=ref('');const deleteId=ref('');const lastSync=ref('');const tokenPrompt=ref(false);const remember=ref(false);const restoreInput=ref([]);const keyHelperOpen=ref(false);const keyType=ref('X25519');const keySecret=ref('');
const cardInfo=computed(()=>settingsCards.find(card=>card[0]===panel.value));
const visibleCards=computed(()=>settingsCards.filter(([key])=>key!=='github'||settings.value.backup.storageType==='gist'));
const schemaData=computed(()=>({values:draft.value,capabilities:props.capabilities}));
const selectedBackend=computed(()=>settings.value.backends.find(item=>item.id===settings.value.currentBackend)||settings.value.backends[0]);
function persist(section){localStorage.setItem(storageKey,JSON.stringify({version:2,values:settings.value}));emit('change',{section,values:clone(settings.value)})}
function open(key){if(key==='logs'){emit('open-logs');return}panel.value=key;notice.value='';confirmation.value='';backendEdit.value=null;backendError.value='';duplicateBackend.value=null;tokenPrompt.value=false;draft.value=clone(settings.value[key]||{});nextTick(()=>dialog.value.showModal())}
function close(){dialog.value?.close();panel.value='';backendEdit.value=null}
function save(values){settings.value[panel.value]={...settings.value[panel.value],...values};if(panel.value==='github')settings.value.requests.githubApiTimeout=values.githubApiTimeout;if(panel.value==='requests')settings.value.github.githubApiTimeout=values.githubApiTimeout;persist(panel.value);if(panel.value==='appearance')applyTheme();notice.value=panel.value==='language'?copy.languages:copy.saved}
function applyTheme(){const a=settings.value.appearance;document.documentElement.dataset.theme=a.themeAuto?(matchMedia('(prefers-color-scheme: dark)').matches?a.themeDark:a.themeLight):a.themeName}
function startBackend(item){backendError.value='';duplicateBackend.value=null;backendEdit.value=item?.id||'new';backendDraft.value=item?clone(item):{name:'',url:'',shareBaseUrl:''}}
function normalizeAddress(input){const value=input.trim();if(!value)return '';if(/^https?:\/\//i.test(value)){try{const u=new URL(value);return u.href.replace(/\/$/,'')}catch{return ''}}if(value.includes('://'))return '';if(/^(localhost|(?:\d{1,3}\.){3}\d{1,3})(:\d+)?(?:\/|$)/i.test(value)&&!/^([^/]+):\d+(?:\/|$)/.test(value))return '';if(/^[^/\s]+:\d+(?:\/.*)?$/.test(value)){try{return new URL('http://'+value).href.replace(/\/$/,'')}catch{return ''}}if(/\s/.test(value))return '';return new URL(value.startsWith('/')?value:'/'+value,location.origin).href.replace(/\/$/,'')}
const parsedBackend=computed(()=>normalizeAddress(backendDraft.value.url||''));
function validShare(value){if(!value)return true;try{return ['http:','https:'].includes(new URL(value).protocol)}catch{return false}}
function submitBackend(values){backendError.value='';const url=normalizeAddress(values.url);if(!url||!validShare(values.shareBaseUrl)){backendError.value=copy.backendBad;return}if(settings.value.backends.some(item=>item.id!==backendEdit.value&&item.name===values.name.trim())){backendError.value=copy.backendNameDuplicate;return}const duplicate=settings.value.backends.find(item=>item.id!==backendEdit.value&&normalizeAddress(item.url)===url);backendDraft.value={...values,name:values.name.trim(),url};if(duplicate){duplicateBackend.value=duplicate;return}commitBackend()}
function commitBackend(overwriteId){const id=overwriteId||(backendEdit.value==='new'?'demo-'+Date.now():backendEdit.value);const previous=settings.value.backends.find(item=>item.id===id);const value={...backendDraft.value,id,isDefault:!!previous?.isDefault};if(previous)settings.value.backends=settings.value.backends.map(item=>item.id===id?value:item);else settings.value.backends.push(value);settings.value.currentBackend=id;persist('backends');backendEdit.value=null;duplicateBackend.value=null;notice.value=copy.saved+'；'+copy.checkDemo}
function switchBackend(item){settings.value.currentBackend=item.id;persist('backends');notice.value=copy.checkDemo}
async function copyBackend(item){const url=new URL(location.origin+location.pathname);url.searchParams.set('api',item.url);if(item.shareBaseUrl)url.searchParams.set('shareBaseUrl',item.shareBaseUrl);try{await navigator.clipboard.writeText(url.href);notice.value=copy.copied}catch{notice.value=copy.copyFailed+'：'+url.href}}
function ask(kind,id=''){confirmation.value=kind;deleteId.value=id;notice.value=''}
function confirm(){if(confirmation.value==='backend'){settings.value.backends=settings.value.backends.filter(item=>item.id!==deleteId.value);if(settings.value.currentBackend===deleteId.value)settings.value.currentBackend='default';persist('backends');notice.value=copy.saved}else if(confirmation.value==='front'){settings.value=clone(defaultSettings);localStorage.removeItem(storageKey);draft.value=clone(settings.value[panel.value]||{});applyTheme();emit('change',{section:'reset',values:clone(settings.value)});notice.value=copy.clearDone}else notice.value=copy.clearBackendDone;confirmation.value=''}
function githubTransfer(kind){if(!settings.value.github.githubUser.trim()||!settings.value.github.gistToken){notice.value=copy.noGistToken;return}if(kind==='download'&&settings.value.github.gistDownloadTokenStrategy==='ask'){remember.value=false;tokenPrompt.value=true;return}notice.value=kind==='download'?copy.downloadDemo:copy.uploadDemo;lastSync.value=new Date().toLocaleString('zh-CN')}
function finishDownload(strategy){if(remember.value){settings.value.github.gistDownloadTokenStrategy=strategy;persist('github')}tokenPrompt.value=false;notice.value=copy.downloadDemo;lastSync.value=new Date().toLocaleString('zh-CN')}
function exportBackup(){const blob=new Blob([JSON.stringify({format:'sub-store-design-settings',version:2,values:settings.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='sub-store-settings-demo.json';a.click();URL.revokeObjectURL(url);notice.value=copy.exported}
async function restoreBackup(value){const file=value?.[0]?.file;if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=='sub-store-design-settings'||data.version!==2||!data.values||!Array.isArray(data.values.backends))throw new Error();const next=clone(defaultSettings);for(const key of Object.keys(defaultSettings)){if(!(key in data.values))continue;next[key]=typeof next[key]==='object'&&!Array.isArray(next[key])?{...next[key],...data.values[key]}:data.values[key]}settings.value=next;draft.value=clone(settings.value.backup);persist('restore');applyTheme();notice.value=copy.restored}catch{notice.value=copy.restoreInvalid}}
function makeDemoKey(){keySecret.value='AGE-SECRET-KEY-'+keyType.value+'-DEMO-NOT-VALID';notice.value=copy.ageCopied}
async function copySecret(){try{await navigator.clipboard.writeText(keySecret.value);notice.value=copy.copied}catch{notice.value=copy.copyFailed}}
function navigate(key){close();emit('navigate',key)}
</script>
<template>
 <section class="settings-list settings-complete" aria-label="设置">
  <button v-for="[key,title,description,icon] in visibleCards" :key="key" class="setting-card" @click="open(key)"><span class="setting-icon"><FontAwesomeIcon :icon="icons[icon]" aria-hidden="true" /></span><span><strong>{{ title }}</strong><small>{{ description }}</small></span><FontAwesomeIcon :icon="icons.faChevronRight" aria-hidden="true" /></button>
  <div class="settings-secondary"><button v-if="capabilities.share" class="button" @click="navigate('shares')">{{ copy.share }}</button><button v-if="capabilities.archive" class="button" @click="navigate('archives')">{{ copy.archives }}</button></div>
 </section>
 <dialog ref="dialog" class="settings-detail" aria-labelledby="settings-detail-title" @close="panel='';backendEdit=null">
  <div class="settings-detail-heading"><h2 id="settings-detail-title">{{ cardInfo?.[1] }}</h2><IconButton label="close" icon="faXmark" @activate="close" /></div>
  <p class="settings-demo">{{ copy.demo }}</p>
  <p v-if="notice" class="settings-result" role="status">{{ notice }}</p>
  <template v-if="confirmation"><p>{{ confirmation==='backend'?copy.confirmDelete:confirmation==='front'?copy.clearConfirm:copy.clearBackendConfirm }}</p><div class="settings-actions"><button class="button" @click="confirmation=''">{{ copy.cancel }}</button><button class="button danger-button" @click="confirm">{{ copy.confirm }}</button></div></template>
  <template v-else-if="panel==='backends'">
   <p class="field-note">{{ copy.backendEnv }}</p>
   <template v-if="!backendEdit"><article v-for="item in settings.backends" :key="item.id" class="settings-backend"><div><strong>{{ item.name }}</strong><span v-if="settings.currentBackend===item.id" class="settings-current">{{ copy.current }}</span><p>{{ item.url }}</p><p v-if="item.shareBaseUrl">{{ item.shareBaseUrl }}</p></div><div class="settings-backend-actions"><button class="button" :disabled="settings.currentBackend===item.id" @click="switchBackend(item)">{{ copy.backendSwitch }}</button><IconButton :label="copy.backendCopy" icon="faClone" @activate="copyBackend(item)" /><IconButton :label="copy.backendEdit" icon="faPenNib" @activate="startBackend(item)" /><IconButton v-if="!item.isDefault" :label="copy.backendDelete" icon="faTrashCan" danger @activate="ask('backend',item.id)" /></div></article><button class="button primary" @click="startBackend()">{{ copy.backendAdd }}</button></template>
   <template v-else><FormKit :key="backendEdit" type="form" v-model="backendDraft" :actions="false" @submit="submitBackend" :incomplete-message="false"><FormKitSchema :schema="backendSchema" /><p class="settings-address">{{ copy.backendPreview }}<br><code>{{ parsedBackend||'—' }}</code></p><p v-if="backendError" class="danger-text" role="alert">{{ backendError }}</p><p v-if="duplicateBackend" class="settings-demo">{{ copy.backendDuplicate }}</p><div v-if="duplicateBackend" class="settings-actions"><button class="button" type="button" @click="switchBackend(duplicateBackend);backendEdit=null;duplicateBackend=null">{{ copy.duplicateSwitch }}</button><button class="button primary" type="button" @click="commitBackend(duplicateBackend.id)">{{ copy.duplicateOverwrite }}</button></div><div v-else class="settings-actions"><button type="button" class="button" @click="backendEdit=null">{{ copy.cancel }}</button><button type="button" class="button" @click="notice=copy.checkDemo">{{ copy.backendCheck }}</button><button type="submit" class="button primary">{{ copy.save }}</button></div></FormKit></template>
  </template>
  <template v-else-if="panel==='about'"><p>{{ copy.aboutVersion }}</p><p class="field-note">{{ environment.name }} · {{ environment.backend }} · {{ environment.version }}</p><a v-if="environment.hasNewVersion" :href="environment.backend==='Node'?'https://github.com/sub-store-org/Sub-Store/releases':'https://github.com/sub-store-org/Sub-Store/tree/master/config'" target="_blank" rel="noopener noreferrer" class="text-link">{{ copy.updated }}</a><p>{{ copy.backendEnv }}</p><p class="field-note">{{ selectedBackend?.name }}</p><div class="settings-about-links"><a v-for="[title,url] in aboutLinks" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{ title }} ↗</a></div></template>
  <template v-else-if="panel">
   <FormKit :key="panel" type="form" v-model="draft" :actions="false" @submit="save" :incomplete-message="false"><FormKitSchema :schema="settingsSchemas[panel]||[]" :data="schemaData" /><div v-if="panel==='github'&&draft.gistUpload==='age'" class="settings-key-helper"><button type="button" class="button" @click="keyHelperOpen=!keyHelperOpen">{{ keyHelperOpen?copy.keyClose:copy.keyHelper }}</button><template v-if="keyHelperOpen"><FormKit type="select" v-model="keyType" name="demoKeyType" :ignore="true" :label="copy.keyType" :options="['X25519','MLKEM768-X25519']" /><FormKit type="textarea" v-model="keySecret" name="demoSecretKey" :ignore="true" :label="copy.keySecret" /><div class="settings-actions"><button type="button" class="button" @click="makeDemoKey">{{ copy.keyGenerate }}</button><button type="button" class="button" :disabled="!keySecret" @click="copySecret">{{ copy.keyCopy }}</button><button type="button" class="button" :disabled="!keySecret" @click="draft.ageSecretKey=keySecret;notice=copy.ageCopied">{{ copy.keyApply }}</button><button type="button" class="button" :disabled="!keySecret" @click="keySecret=''">{{ copy.keyClear }}</button></div></template><p class="field-note">{{ copy.keyNotice }}</p></div><div class="settings-actions"><button type="button" class="button" @click="close">{{ copy.cancel }}</button><button type="submit" class="button primary">{{ copy.save }}</button></div></FormKit>
   <div v-if="panel==='backup'" class="settings-backup-actions">
    <template v-if="draft.storageType==='gist'"><p>{{ copy.githubNotice }}</p><button class="text-link" @click="open('github')">{{ copy.gotoGithub }}</button><p v-if="!settings.github.gistToken" class="field-note">{{ copy.noGistToken }}</p><p class="field-note">{{ settings.github.githubUser }} · {{ copy.lastSync }}：{{ lastSync||copy.never }}</p><div v-if="tokenPrompt" class="settings-token-prompt"><h3>{{ copy.tokenTitle }}</h3><p class="field-note">{{ copy.downloadHint }}</p><FormKit type="checkbox" v-model="remember" :label="copy.remember" /><div class="settings-actions"><button class="button" @click="tokenPrompt=false">{{ copy.cancel }}</button><button class="button" @click="finishDownload('keep')">{{ copy.tokenKeep }}</button><button class="button primary" @click="finishDownload('overwrite')">{{ copy.tokenOverwrite }}</button></div></div><div v-else class="settings-actions"><button class="button" :disabled="!settings.github.gistToken" @click="githubTransfer('upload')">{{ copy.upload }}</button><button class="button primary" :disabled="!settings.github.gistToken" @click="githubTransfer('download')">{{ copy.download }}</button></div></template>
    <template v-else><p class="field-note">{{ copy.restoreHelp }}</p><button class="button" @click="exportBackup">{{ copy.manualBackup }}</button><FormKit type="file" v-model="restoreInput" accept="application/json,.json" :label="copy.manualRestore" :help="copy.file" @input="restoreBackup" /></template>
   </div>
   <div v-if="panel==='appearance'" class="settings-danger-zone"><button class="button danger-text" @click="ask('front')">{{ copy.clearFront }}</button><button class="button danger-text" @click="ask('backendData')">{{ copy.clearBackend }}</button></div>
  </template>
 </dialog>
</template>
<style scoped>
.settings-complete{max-width:780px}.settings-secondary{display:flex;gap:12px;flex-wrap:wrap}.settings-detail{width:min(680px,calc(100% - 32px));max-height:calc(100dvh - 48px);padding:24px;overflow:auto;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:var(--radius)}.settings-detail-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.settings-detail-heading h2{margin:0;font-size:20px}.settings-demo{font-size:12px;line-height:1.8;color:var(--muted);margin:0 0 24px}.settings-result{position:sticky;top:-24px;background:var(--accent-soft);color:var(--accent);padding:12px 16px;border-radius:10px;font-size:13px;z-index:2;overflow-wrap:anywhere}.settings-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px;margin:24px 0 8px}.settings-backend{border-bottom:1px solid var(--line);padding:20px 0}.settings-backend>div:first-child{overflow-wrap:anywhere}.settings-backend strong{font-size:15px}.settings-backend p{margin:6px 0;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.settings-current{color:var(--accent);font-size:11px;margin-left:12px}.settings-backend-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:12px}.settings-backend-actions .button{margin-right:auto}.settings-address{padding:12px;background:var(--bg);border-radius:8px;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.settings-key-helper,.settings-backup-actions,.settings-danger-zone{padding-top:20px;margin-top:20px;border-top:1px solid var(--line)}.settings-key-helper p{margin-top:12px}.settings-danger-zone{display:flex;gap:12px;flex-wrap:wrap}.settings-backup-actions>p{font-size:13px;color:var(--muted)}.settings-about-links{display:grid;gap:8px}.settings-about-links a{min-height:44px;padding:10px 0;color:var(--accent);border-bottom:1px solid var(--line)}.settings-token-prompt{background:var(--bg);padding:16px;border-radius:12px;margin-top:16px}.settings-token-prompt h3{margin-top:0;font-size:16px}.settings-detail :deep(h3){font-size:15px;margin:28px 0 16px;padding-top:16px;border-top:1px solid var(--line)}.settings-detail :deep(.formkit-outer){margin-bottom:20px}.settings-detail :deep(.formkit-input:not([type=checkbox]):not([type=radio])){font-size:16px;width:100%;min-height:44px}.settings-detail :deep(.formkit-label){color:var(--text)}.settings-detail :deep(.formkit-help){font-size:12px;color:var(--muted)}.settings-detail :deep(.formkit-message){font-size:12px;color:var(--danger)}@media(max-width:700px){.settings-detail{padding:20px;max-height:calc(100dvh - 32px)}.settings-result{top:-20px}.settings-detail-heading h2{font-size:19px}.settings-actions .button{font-size:12px;padding:10px 12px}}
</style>
